import { Hono } from "hono";
import { z } from "zod";
import {
  attendances,
  attendanceId,
  chunk,
  conferences,
  nowIso,
  users,
} from "../lib/firestore";
import { AppEnv, getUserId, maybeUserId, optionalAuth, requireAuth } from "../auth";

export const conferenceRoutes = new Hono<AppEnv>();

type ConferenceData = {
  name: string;
  location_name: string;
  latitude: number;
  longitude: number;
  start_date: string;
  end_date: string;
  source?: string;
  topics?: string[];
  url?: string | null;
  created_at: string;
};

function toApiConference(id: string, data: FirebaseFirestore.DocumentData) {
