:root {
  --void: #03040a;
  --haze: #0c1020;
  --mist: rgba(232, 240, 255, 0.08);
  --mist-strong: rgba(232, 240, 255, 0.16);
  --ember: #f6d4a3;
  --ember-hot: #fff4e0;
  --signal: #5ee7d9;
  --signal-dim: rgba(94, 231, 217, 0.35);
  --past-signal: #8ca0dc;
  --past-ember: #c3a0b4;
  --danger: #ff6b8a;
  --text: #e8f0ff;
  --text-muted: rgba(232, 240, 255, 0.55);
  --panel-gradient: linear-gradient(
    180deg,
    rgba(16, 20, 40, 0.78) 0%,
    rgba(6, 8, 20, 0.82) 100%
  );
}

html,
body,
#root {
  height: 100%;
  margin: 0;
  background: var(--void);
  color: var(--text);
  font-family: "Lexend Exa", "SF Pro", system-ui, sans-serif;
  font-weight: 300;
  letter-spacing: 0.04em;
  -webkit-font-smoothing: antialiased;
}

* {
  box-sizing: border-box;
}

button {
  font-family: inherit;
  letter-spacing: 0.04em;
  color: inherit;
  background: none;
  border: none;
  cursor: pointer;
}

input,
textarea,
select {
  font-family: inherit;
  color: inherit;
  background: transparent;
  border: 1px solid var(--mist);
  border-radius: 999px;
  padding: 0.5rem 0.85rem;
  outline: none;
  transition: border-color 180ms ease;
  font-size: 0.8rem;
  letter-spacing: 0.06em;
}

input:focus {
  border-color: var(--signal-dim);
}

.glass-panel {
  background: var(--panel-gradient);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  border: 1px solid var(--mist);
  border-radius: 18px;
  color: var(--text);
  box-shadow: 0 10px 40px -15px rgba(0, 0, 0, 0.9);
}

.soft-button {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  padding: 0.55rem 1rem;
  border-radius: 999px;
  border: 1px solid var(--mist);
