          align-items: center;
        }
        .conf-name {
          margin: 0;
          font-size: 1.3rem;
          font-weight: 400;
          line-height: 1.2;
        }
        .topics {
          display: flex;
          gap: 0.4rem;
          flex-wrap: wrap;
        }
        .topic-chip {
          font-size: 0.6rem;
          text-transform: uppercase;
          letter-spacing: 0.14em;
          padding: 0.2rem 0.55rem;
          border: 1px solid var(--mist);
          border-radius: 999px;
          color: var(--text-muted);
