        <div className="my-list">
          {going.map((c) => (
            <button key={c.id} className="my-row mine" onClick={() => onPick(c)}>
              <span className="my-row-date signal-tint">
                {new Date(c.startDate).toLocaleDateString()}
              </span>
              <span className="my-row-name">{c.name}</span>
