() => {
  // Click the map canvas programmatically — simulate a click on Minneapolis (~44.97, -93.26).
  const canvas = document.querySelector('.mapboxgl-canvas');
  if (!canvas) return { ok: false, reason: 'no canvas' };
  const rect = canvas.getBoundingClientRect();
  // compute Minneapolis screen coords via mapboxgl project()
  const map = window.__mbmap;
  return { ok: true, w: rect.width, h: rect.height, hasMap: Boolean(map) };
}

